message.content:
{
  "hypotheses": [
    {
      "team": "home",
      "reasons": [
        {
          "text": "미국은 최근 5경기에서 4승을 거두며 경기당 2.8골(보정 2.0)을 넣어 공격 생산이 꾸준하다.",
          "var_ids": ["S01-home"]
        },
        {
          "text": "미국은 3경기 연속 무패 흐름을 이어가고 있다.",
          "var_ids": ["IR12-home"]
        },
        {
          "text": "미네소타 홈에서 치르는 경기라 상대보다 이동·환경 부담이 적다.",
          "var_ids": ["S03"]
        }
      ],
      "breaks": [
        {
          "text": "8일 안에 이번이 3번째 경기라 일정 과부하로 후반 체력이 떨어질 수 있다.",
          "var_ids": ["IR11-home"]
        },
        {
          "text": "친선 경기라 실험 라인업과 잦은 교체로 전력 연결이 끊길 수 있다.",
          "var_ids": ["S04"]
        }
      ]
    },
    {
      "team": "away",
      "reasons": [
        {
          "text": "미국이 8일 안에 3경기를 치르는 과부하 상태라 캐나다가 체력에서 상대 우위를 가질 수 있다.",
          "var_ids": ["IR11-home"]
        },
        {
          "text": "캐나다는 최근 5경기에서 승패가 엇갈렸지만 마지막 두 경기를 연속 승리로 마무리했다.",
          "var_ids": ["S01-away"]
        },
        {
          "text": "감독이 선수 부담 관리를 염두에 두고 운영해 캐나다가 상대보다 정돈된 체력 배분으로 맞설 수 있다.",
          "var_ids": ["R3"]
        }
      ],
      "breaks": [
        {
          "text": "주 공격수 Cyle Larin이 허리 부상으로 선발에서 제외되어 득점 루트가 줄어든다.",
          "var_ids": ["R1"]
        },
        {
          "text": "최근 5경기 득점 평균이 1.0(보정 0.75)에 그쳐 마무리 결정력이 낮다.",
          "var_ids": ["S01-away"]
        },
        {
          "text": "친선 경기라 캐나다도 로테이션을 돌리면 조직력이 흔들릴 수 있다.",
          "var_ids": ["S04", "R3"]
        }
      ]
    }
  ],
  "scenarios": [
    {
      "id": "s1-대량득점형",
      "outcomes": [[3, 1], [4, 2]],
      "driver_vars": ["S01-home", "S03", "S04", "IR11-home"],
      "mechanism": "미국의 최근 경기당 2.8골 생산과 홈 환경이 맞물려 전방 압박이 초반부터 득점으로 이어지고, 친선 특유의 열린 전개 속에 미국의 일정 과부하가 후반 실점을 허용한다."
    },
    {
      "id": "s2-우세팀_실점_동반형",
      "outcomes": [[2, 1], [3, 2]],
      "driver_vars": ["IR12-home", "S01-home", "R1", "S04"],
      "mechanism": "미국의 무패 흐름과 꾸준한 득점력이 주도권을 만들지만, 친선 경기의 잦은 교체로 수비 집중력이 흔들리고 캐나다가 라린 결장에도 세트피스 한 번으로 따라붙는다."
    },
    {
      "id": "s3-핸디_대응형",
      "outcomes": [[2, 0], [1, 0]],
      "driver_vars": ["S03", "IR12-home", "S04", "IR11-home"],
      "mechanism": "미국이 홈에서 수비 라인을 낮추지 않고 경기를 통제하며 캐나다의 낮은 최근 득점 생산을 묶어 실점 없이 마무리한다."
    },
    {
      "id": "s4-회귀_반전형",
      "outcomes": [[0, 1], [1, 2]],
      "driver_vars": ["IR11-home", "S01-away", "R3", "S04"],
      "mechanism": "8일 3경기 과부하로 미국의 압박 강도가 경기 중반 이후 급격히 떨어지고, 캐나다가 부담 관리된 전력으로 역습 한두 번을 득점으로 전환한다."
    },
    {
      "id": "s5-친선_교착형",
      "outcomes": [[1, 1], [2, 2]],
      "driver_vars": ["S04", "R3", "IR11-home", "S01-away"],
      "mechanism": "친선 경기 특성상 양 팀이 실험 라인업과 잦은 교체를 쓰면서 흐름이 자주 끊기고, 미국의 체력 저하와 캐나다의 낮은 마무리 효율이 맞물려 서로 한 골씩 주고받는다."
    }
  ]
}
